// Transforma a resposta da Adzuna em 1 item por vaga, só com o que interessa
const results = $input.first().json.results ?? [];

return results.map(v => ({
  json: {
    id: 'a' + String(v.id),
    titulo: v.title,
    empresa: v.company?.display_name ?? 'Não informada',
    local: v.location?.display_name ?? 'Não informada',
    link: v.redirect_url,
    descricao: (v.description ?? '').slice(0, 600),
    publicada_em: v.created,
    fonte: 'Adzuna',
  },
}));

// Junta a avaliação da IA com os dados originais das vagas e ordena por score
const vagas = $('Aggregate').first().json.vagas;
const bruto = $input.first().json.text ?? $input.first().json.output ?? '';

let avaliacoes;
try {
  // Remove cercas de código caso o modelo desobedeça o "sem markdown"
  const limpo = String(bruto).replace(/```json|```/g, '').trim();
  avaliacoes = JSON.parse(limpo);
} catch (e) {
  // Fallback: se o JSON vier quebrado, envia as vagas sem score em vez de perder o dia
  return [{ json: { fallback: true, vagas } }];
}

const porId = Object.fromEntries(avaliacoes.map(a => [String(a.id), a]));
const ranqueadas = vagas
  .map(v => ({ ...v, ...(porId[String(v.id)] ?? { score: 0, motivo: 'Sem avaliação', destaque: false }) }))
  .sort((a, b) => b.score - a.score);

return [{ json: { fallback: false, vagas: ranqueadas } }];

const { fallback, vagas } = $input.first().json;
const hoje = new Date().toLocaleDateString('pt-BR');

if (fallback) {
  const linhas = vagas.slice(0, 10).map(v => `• ${v.titulo} — ${v.empresa}\n${v.link}`);
  return [{ json: { texto: `📡 Radar de Vagas — ${hoje}\n⚠️ IA indisponível hoje; vagas sem ranking:\n\n${linhas.join('\n\n')}` } }];
}

const NOTA_MINIMA = 4; // ajuste fino: só vagas com score >= 4 entram na mensagem
const medalha = i => ['🥇', '🥈', '🥉'][i] ?? '▪️';
const fontes = [...new Set(vagas.map(v => v.fonte))];

const mensagens = fontes.map(f => {
  const doFonte = vagas.filter(v => v.fonte === f && v.score >= NOTA_MINIMA).slice(0, 10);
  if (doFonte.length === 0) return null; // fonte sem vaga boa hoje = sem mensagem dela
  const linhas = doFonte.map((v, i) =>
    `${medalha(i)} <b>${v.score}/10 — ${v.titulo}</b>\n${v.empresa} · ${v.local}\n<i>${v.motivo}</i>\n<a href="${v.link}">Ver vaga</a>`
  );
  return { json: { texto: `📡 <b>Radar de Vagas — ${f} — ${hoje}</b>\n${doFonte.length} vaga(s) com fit:\n\n${linhas.join('\n\n')}` } };
}).filter(Boolean);

if (mensagens.length === 0) {
  return [{ json: { texto: `📡 Radar de Vagas — ${hoje}\nNenhuma vaga nova com fit hoje. Radar segue de olho. 👀` } }];
}

return mensagens;

const jobs = $input.first().json.jobs ?? [];
return jobs.map(j => ({
  json: {
    id: 'j' + String(j.id).replace(/[^0-9]/g, ''),
    titulo: j.title,
    empresa: j.company || 'Não informada',
    local: j.location || 'Não informada',
    link: j.link,
    descricao: String(j.snippet ?? '').replace(/<[^>]+>/g, '').slice(0, 600),
    publicada_em: j.updated,
    fonte: 'Jooble',
  },
}));
